code.cpp:
class Solution {
public:
    int maxProduct(string s) {
        int n = s.size();
        int full = (1 << n) - 1;
        vector<int> palLen(1 << n, 0);

        for (int mask = 1; mask <= full; mask++) {
            string t;
            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) t.push_back(s[i]);
            }
            int m = t.size();
            bool ok = true;
            for (int i = 0; i < m / 2; i++) {
                if (t[i] != t[m - 1 - i]) { ok = false; break; }
            }
            if (ok) palLen[mask] = m;
        }

        vector<int> best(1 << n, 0);
        for (int mask = 0; mask <= full; mask++) best[mask] = palLen[mask];
        for (int i = 0; i < n; i++) {
            for (int mask = 0; mask <= full; mask++) {
                if (mask & (1 << i)) {
                    best[mask] = max(best[mask], best[mask ^ (1 << i)]);
                }
            }
        }

        int ans = 0;
        for (int mask = 1; mask <= full; mask++) {
            if (palLen[mask] > 0) {
                int comp = full ^ mask;
                ans = max(ans, palLen[mask] * best[comp]);
            }
        }
        return ans;
    }
};
